import{_ as d,C as r,o as n,c as o,E as a,a4 as i}from"./chunks/framework.BMj-uaUw.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一周要“建仓库”","slug":"这一周要-建仓库","link":"#这一周要-建仓库","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit03/index.md","filePath":"unit03/index.md","lastUpdated":1789356894000}'),s={name:"unit03/index.md"};function l(c,t,h,p,g,u){const e=r("UnitMeta");return n(),o("div",null,[a(e,{unit:"单元 3",title:"工程规范、质量保障与 Git 协作",module:"模块一 · 工程化认知与工具链",hours:"4 学时",week:"第 3 周",goals:["能配置并解释一套前端代码检查方案，让检查在编辑与提交两个环节自动生效","能按模块化思路组织代码文件","能规范使用 Git 完成一次完整的功能开发与合并","能配置一条自动构建流水线"],outcomes:["带校验钩子的工程模板","首次合并请求 + 自动构建流水线"]}),t[0]||(t[0]=i(`<h2 id="这一周要-建仓库" tabindex="-1">这一周要“建仓库” <a class="header-anchor" href="#这一周要-建仓库" aria-label="Permalink to &quot;这一周要“建仓库”&quot;">​</a></h2><p>前面两周都在自己的电脑上折腾：装环境、配构建、调依赖。这一周不一样 —— <strong>这一周你要和同学一起，在一个共享的仓库里写代码。</strong></p><p>一旦代码不再只有你看，问题就换了一批：</p><table tabindex="0"><thead><tr><th>单人开发</th><th>多人协作</th></tr></thead><tbody><tr><td>缩进用空格还是 Tab 随意</td><td>一次提交里混进几百行“格式改动”，评审没法看</td></tr><tr><td>变量名随手起</td><td>别人读不懂你写的 <code>data2</code>、<code>tmp</code>、<code>listNew</code></td></tr><tr><td>提交信息写“改了一下”</td><td>出了问题想回退，找不到是哪次提交引入的</td></tr><tr><td>本地跑通就提交</td><td>有人提交的代码根本构建不过</td></tr><tr><td>直接改主分支上的代码</td><td>两个人改同一个文件，冲突了不会解</td></tr></tbody></table><p>这五条对应本单元的五节内容。它们不是“高级技巧”，而是<strong>你从今天开始每天都要用的东西</strong>。</p><div class="warning custom-block"><p class="custom-block-title">这个单元是整门课的转折点</p><p>第 1、2 周是“把工具装好”，从这一周开始是“<strong>在一个真实的仓库里协作</strong>”。</p><p>本单元结束时你会有一个<strong>工程模板</strong> —— 它包含构建配置、代码检查、提交钩子、流水线。 第 11 周做综合项目时，<strong>不是从零开始，而是直接从这个模板开始</strong>。</p><p>所以这一周的产出不是练习题，是<strong>你要一直用下去的东西</strong>。认真做。</p></div><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit03/01-why-lint.html">3.1 为什么需要代码规范</a></td><td>评审成本、格式争论、规范的三层划分</td><td>为什么这件事必须自动化</td></tr><tr><td><a href="/frontend-engineering-course/unit03/02-eslint-prettier.html">3.2 ESLint 与 Prettier 配置</a></td><td>扁平配置、规则集、职责划分、编辑器联动、提交钩子</td><td>怎么让检查自动生效</td></tr><tr><td><a href="/frontend-engineering-course/unit03/03-modules-structure.html">3.3 模块化与目录组织</a></td><td>ES Module、导出方式取舍、按功能分目录、命名约定</td><td>代码怎么组织才不越写越乱</td></tr><tr><td><a href="/frontend-engineering-course/unit03/04-git-flow.html">3.4 Git 协作流程</a></td><td>分支模型、提交信息、冲突解决、代码评审、<code>.gitignore</code></td><td>两个人怎么安全地改同一份代码</td></tr><tr><td><a href="/frontend-engineering-course/unit03/05-ci.html">3.5 自动构建流水线</a></td><td>四个阶段、本地能过流水线不过的原因、门禁的价值</td><td>怎么不靠人工自觉</td></tr><tr><td><a href="/frontend-engineering-course/unit03/ai-collaboration.html">AI 协作 · AGENTS.md 与提交规范</a></td><td>AGENTS.md 是什么、写什么、怎么分层，配合提交信息规范</td><td>让 AI 按项目约定产出，而不是按它自己的习惯</td></tr><tr><td><a href="/frontend-engineering-course/unit03/practice.html">课后练习</a></td><td>规范治理、钩子拦截、两人协作评审、流水线跑绿</td><td>把这些配置真的用起来</td></tr></tbody></table><p>五节的顺序是一条链：<strong>先有规范意识（3.1）→ 用工具把规范自动执行（3.2）→ 代码本身组织得好（3.3）→ 协作流程规范（3.4）→ 把检查接到流水线上（3.5）</strong>。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：你遇到过哪些“格式争论”？你现在的提交信息都写成什么样？</td></tr><tr><td>讲解</td><td>1.2 学时</td><td>重点讲 3.2 的检查链路与 3.4 的冲突解决；3.1、3.3、3.5 以自学 + 答疑为主</td></tr><tr><td>现场任务</td><td>1.9 学时</td><td>配好检查与钩子，两人一组各自开分支实现一个小功能并合并</td></tr><tr><td>复盘</td><td>0.6 学时</td><td>展示几组被钩子拦下的提交，对比不同分支的冲突解决方式</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易卡住的地方</p><p>不是配置本身，是<strong>提交钩子不生效</strong>。</p><p><code>husky</code> 需要在 Git 仓库里初始化；<code>lint-staged</code> 需要和 <code>husky</code> 配合； 配置写完后要<strong>真的做一次提交</strong>才能验证。三个环节里任何一个没做对， 表现都是“提交居然通过了” —— 而且不报错，你根本不知道它没生效。</p><p><strong>验证方法只有一个：故意提交一次不合规的代码，看它有没有被拦下来。</strong> 练习里专门有一道题做这件事，不要跳过。</p></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>三样准备。前两样第 2 周应该已经完成。</p><ul><li><strong>一个能构建的项目</strong>：练习 1 修好的那个工程，能跑 <code>pnpm build</code>。</li><li><strong>一份可用的 <code>vite.config.js</code></strong>：带别名和代理配置。</li><li><strong>一个 GitHub 或云效的账号</strong>：这一周要建远程仓库、开合并请求。 校内可以统一用学校提供的代码托管平台。</li></ul><p>另外<strong>找一个搭档</strong>。3.4 的冲突场景需要两个人真的改同一个文件才能体会到 —— 一个人自己造冲突，是体会不到“评审时该看什么”的。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同学 A：负责活动列表页的活动状态筛选功能</span></span>
<span class="line"><span>同学 B：负责活动列表页的时间格式化功能</span></span>
<span class="line"><span>两个人都会改 src/views/ActivityListView.vue —— 冲突就是这样产生的</span></span></code></pre></div><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p>按课程要求，这次课交两样东西。</p><p><strong>一、带校验钩子的工程模板</strong></p><p>一个可以直接复制用来开新项目的仓库，至少包含：</p><table tabindex="0"><thead><tr><th>组成部分</th><th>要求</th></tr></thead><tbody><tr><td>构建配置</td><td>可用的 <code>vite.config.js</code>、环境变量文件</td></tr><tr><td>代码检查</td><td>ESLint 配置 + Prettier 配置，职责不重叠</td></tr><tr><td>提交校验</td><td>husky + lint-staged + commitlint，提交不合规时被拦下</td></tr><tr><td>编辑器说明</td><td><code>.vscode/settings.json</code> 与推荐扩展列表</td></tr><tr><td>说明文档</td><td><code>README.md</code> 写清楚怎么装、怎么跑、怎么提交</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">判断模板合格的三条标准</p><ol><li><strong>新人克隆后能跑起来</strong>：不做任何额外确认，照着 <code>README.md</code> 三步内启动。</li><li><strong>不合规的代码提交不上去</strong>：格式错误、提交信息不规范都会被拦。</li><li><strong>检查在编辑器里就能看到</strong>：不用等到提交才发现问题。</li></ol><p>第 3 条最容易被忽略，但它是“规范能不能长期维持”的关键 —— <strong>要等提交才发现问题，人就会想办法绕过检查。</strong></p></div><p><strong>二、首次合并请求 + 自动构建流水线</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>分支</td><td>从主分支切出一个功能分支，命名规范</td></tr><tr><td>提交</td><td>至少 3 次提交，信息符合约定格式</td></tr><tr><td>评审</td><td>有一次真实的互相评审，留下评论并说明采纳理由</td></tr><tr><td>合并</td><td>合并前流水线跑绿</td></tr><tr><td>流水线</td><td>安装依赖 → 执行检查 → 构建，三个阶段都通过</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">不要为了“跑绿”而关掉检查</p><p>流水线第一次跑，通常会因为一些历史代码的问题失败。这时候有两种处理方式：</p><ul><li>把出问题的规则临时关掉 —— 三周后你会发现规则全被关光了。</li><li><strong>只修本次改动涉及的文件，其余问题记成待办。</strong></li></ul><p>选第二种。<strong>门禁的意义是“不让问题变多”，不是“立刻让所有问题归零”。</strong></p></div><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>这个单元结束之后，你手上有三样东西：一个能构建的工程、一套自动检查、 一个能跑的流水线。<strong>它们就是第 4 周开始写 Vue 代码的工作台。</strong></p><p>下一单元（<a href="/frontend-engineering-course/unit04/">单元 4</a>）开始讲 Vue 3 的模板语法与响应式。到那时候， 你每写一行代码都会被格式化、被检查、被流水线验证 —— 这正是我们想要的状态： <strong>把规范交给工具，把注意力留给业务逻辑。</strong></p><p>如果这个单元学得吃力，优先保证 3.2（检查链路）和 3.4（Git 流程）过关。 这两节是后面每周都要用的。</p><hr><p>下一节：<a href="/frontend-engineering-course/unit03/01-why-lint.html">3.1 为什么需要代码规范</a></p>`,32))])}const f=d(s,[["render",l]]);export{m as __pageData,f as default};
